package com.tregy.backend.service.impl;
import com.tregy.backend.dto.request.UpdateMeRequestDTO;import com.tregy.backend.dto.response.UserResponseDTO;import com.tregy.backend.exception.AuthException;import com.tregy.backend.model.AppUser;import com.tregy.backend.repository.AppUserRepository;import com.tregy.backend.service.MeService;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class MeServiceImpl implements MeService{private final AppUserRepository users;public MeServiceImpl(AppUserRepository users){this.users=users;}public UserResponseDTO get(String id){return AuthServiceImpl.response(require(id));}@Transactional public UserResponseDTO update(String id,UpdateMeRequestDTO r){AppUser u=require(id);if(r.uiLanguage()!=null)u.setUiLanguage(r.uiLanguage());return AuthServiceImpl.response(users.save(u));}private AppUser require(String id){return users.findById(id).orElseThrow(()->new AuthException("UNAUTHENTICATED","Sign in required"));}}
